private void showCommonBottomDialog() {
    if (this.commonBottomDialog == null) {
        CommonBottomDialog commonBottomDialog = new CommonBottomDialog(requireContext());
        this.commonBottomDialog = commonBottomDialog;
        commonBottomDialog.setCancelText(R.string.str_close_prompt);
        this.commonBottomDialog.setConfirmText(R.string.str_config_again_1);
        this.commonBottomDialog.setTitleText(R.string.str_alarm_time_setting_tips);
        this.commonBottomDialog.setOnClickListener(new CommonBottomDialog.OnClickListener() { // from class: com.macrovideo.v380.fragments.DeviceConfigSettingAlarmTimePlanFragment.12
            @Override // com.macrovideo.v380.ui.CommonBottomDialog.OnClickListener
            public void onClickConfirm() {
                DeviceConfigSettingAlarmTimePlanFragment.this.commonBottomDialog.dismiss();
            }

            @Override // com.macrovideo.v380.ui.CommonBottomDialog.OnClickListener
            public void onClickCancel() {
                AlarmConfigInfo alarmInfo = GlobalDefines.sDeviceConfigure.getAlarmInfo();
                LogUtil.i(DeviceConfigSettingAlarmTimePlanFragment.TAG, "<literal omitted>" + DeviceConfigSettingAlarmTimePlanFragment.this.lastCloseSwitch);
                if (DeviceConfigSettingAlarmTimePlanFragment.this.lastCloseSwitch != TimeBarInfo.STATE_MOVE_MASK) {
                    if (DeviceConfigSettingAlarmTimePlanFragment.this.lastCloseSwitch != TimeBarInfo.STATE_HUMAN_MASK) {
                        if (DeviceConfigSettingAlarmTimePlanFragment.this.lastCloseSwitch != TimeBarInfo.STATE_PIR_MASK) {
                            if (DeviceConfigSettingAlarmTimePlanFragment.this.lastCloseSwitch == TimeBarInfo.STATE_CRY_MASK) {
                                alarmInfo.setCryDetectionSwitch(true);
                            }
                        } else {
                            alarmInfo.setbPIRAlarmSwitch(true);
                        }
                    } else {
                        alarmInfo.setAiSwitch(1);
                    }
                } else {
                    alarmInfo.setbMotionAlarmSwitch(true);
                }
                alarmInfo.setbMainAlarmSwitch(false);
                DeviceConfigSettingAlarmTimePlanFragment.this.saveTimePlan(new AlarmInfoSettingCallback() { // from class: com.macrovideo.v380.fragments.DeviceConfigSettingAlarmTimePlanFragment.12.1
                    @Override // com.macrovideo.v380.fragments.DeviceConfigSettingAlarmTimePlanFragment.AlarmInfoSettingCallback
                    public void onFail() {
                    }

                    @Override // com.macrovideo.v380.fragments.DeviceConfigSettingAlarmTimePlanFragment.AlarmInfoSettingCallback
                    public void onSuccess() {
                        DeviceConfigSettingAlarmTimePlanFragment.this.mActivity.getSupportFragmentManager().popBackStack();
                    }
                });
            }
        });
    }
    this.commonBottomDialog.show();
}
